"""Original teaching following the mathematical sequence of book sections 20.1–20.4."""
import re
import sympy as s
lessons=[];models=[]
def T(v):return s.latex(v,mat_delim='(',mat_str='matrix')
def D(*rows):return r'\[\begin{gathered}'+r'\\'.join(rows)+r'\end{gathered}\]'
def prose_math(text):
 """Typeset powers in prose without touching existing TeX or owner material."""
 chunks=re.split(r'(\\\[.*?\\\]|\\\(.*?\\\))',text,flags=re.S)
 table=str.maketrans('⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿ','-0123456789n')
 for i in range(0,len(chunks),2):
  chunks[i]=re.sub(r'(?:[A-Za-zλ][⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿ]+)+',lambda m:r'\('+re.sub(r'([A-Za-zλ])([⁻⁰¹²³⁴⁵⁶⁷⁸⁹ⁿ]+)',lambda p:p[1]+'^{'+p[2].translate(table)+'}',m[0])+r'\)',chunks[i])
 return ''.join(chunks)
def E(code,title,question,worked,kind,**data):
 uid='MAT2-E-'+code;models.append(dict(id=uid,kind=kind,**data))
 return dict(title=title,question=prose_math(question),solution=prose_math(worked),verification=uid)
def L(key,title,summary,objective,before,ideas,method,mistakes,examples):
 lessons.append(dict(key=key,id='fp2_matrices2_'+key,title=title,summary=summary,objective=objective,before=before,ideas=prose_math(ideas),method=prose_math('<ol>'+''.join('<li>'+z+'</li>' for z in method)+'</ol>'),mistakes=mistakes,examples=examples))
base='/courses/maths4u-9231-fp2/topics/fp2_matrices2_'
def before(key):return '<p>Complete <a href="'+base+key+'">the preceding method</a>. Keep exact fractions and check matrix dimensions.</p>'
A=s.Matrix([[5,2],[0,1]]);B=s.Matrix([[3,2,0],[0,-1,0],[0,0,2]])
L('eigen','Eigenvalues and eigenvectors','Find every real eigenvalue and a non-zero vector for each.',
 'Calculate complete eigensystems and verify each vector by multiplication.',
 '<p>Review <a href="/courses/maths4u-9231-fp1?chapter=fp1_matrices1">Matrices 1</a>: products, determinants, inverses and simultaneous equations.</p>',
 r'''<h3>A direction is scaled</h3><p>An eigenvector is a non-zero column vector whose image is a scalar multiple of itself. The scalar is its eigenvalue. A negative value reverses its direction; zero sends the vector to the origin and is a valid eigenvalue.</p>'''+D(r'A\mathbf v=\lambda\mathbf v,\qquad\mathbf v\ne\mathbf0',r'(A-\lambda I)\mathbf v=\mathbf0',r'\det(\lambda I-A)=0')+r'''<p>The homogeneous equations have a non-zero solution only when the coefficient matrix is singular. This gives the characteristic equation. We use det(λI−A), with leading coefficient +1. Using det(A−λI) gives the same roots, even when its overall sign differs.</p><h3>Find vectors after finding roots</h3><p>For each eigenvalue, solve the homogeneous equations, leave a free variable, then choose a convenient non-zero value. A non-zero multiple is an equally valid eigenvector. A vector of zeros never qualifies. Substitute the resulting vector into the original product.</p><h3>Checks, not substitutes for working</h3><p>For a triangular matrix the diagonal entries are its eigenvalues. In two or three dimensions, the sum of the eigenvalues, counted with multiplicity, is the trace and their product is the determinant. These can check a calculation or complete missing eigenvalues when sufficient information is given. They do not supply eigenvectors.</p>''',
 ['Form λI−A with consistent signs.','Expand and factor its determinant; state every real root.','For each root solve (A−λI)v=0.','Choose a non-zero vector and verify Av=λv.'],
 ['The zero vector is not an eigenvector.','A zero eigenvalue is permitted.','List every required eigenvalue.','An eigenvector can be scaled, but not replaced by an unrelated vector.','A triangular shortcut does not apply to every square matrix.'],[
 E('E1','1 · A complete two-dimensional eigensystem',r'<p>Find all eigenpairs of \(A='+T(A)+r'\).</p>',D(r'\det(\lambda I-A)=(\lambda-5)(\lambda-1)',r'\lambda=5:\quad\mathbf v='+T(s.Matrix([1,0])),r'\lambda=1:\quad\mathbf w='+T(s.Matrix([-1,2])))+'<p>At 5 the second coordinate vanishes. At 1, 4x+2y=0. Both displayed vectors are non-zero; multiplying by A verifies each pair.</p>','eigen',A=A.tolist(),values=[5,1],vectors=[[1,0],[-1,2]]),
 E('E2','2 · Three eigenvalues need three checks',r'<p>Find every eigenpair of \(B='+T(B)+r'\).</p>',D(r'\det(\lambda I-B)=(\lambda-3)(\lambda+1)(\lambda-2)',r'\lambda=3:\ (1,0,0)^{\mathsf T}',r'\lambda=-1:\ (1,-2,0)^{\mathsf T}',r'\lambda=2:\ (0,0,1)^{\mathsf T}')+'<p>Use the triangular diagonal to find all three values, then solve the corresponding homogeneous equations. The trace is 4 and the determinant is −6, agreeing with the sum and product.</p>','eigen',A=B.tolist(),values=[3,-1,2],vectors=[[1,0,0],[1,-2,0],[0,0,1]]),
 E('E3','3 · Use a prescribed eigenvalue',r'<p>The matrix \(M=\begin{pmatrix}a&2\\2&1\end{pmatrix}\) has eigenvalue 5. Find a and a vector for each eigenvalue.</p>',D(r'\det(M-5I)=-4(a-5)-4=0',r'a=4,\qquad\det(\lambda I-M)=\lambda(\lambda-5)',r'\lambda=5:\ (2,1)^{\mathsf T}',r'\lambda=0:\ (1,-2)^{\mathsf T}')+'<p>Only after determining a should you calculate the remaining eigensystem. A zero eigenvalue does not invalidate its non-zero vector.</p>','parameter_eigen',a=4),
 E('E4','4 · A singular matrix still has eigenvectors',r'<p>Find all eigenpairs of \(C=\begin{pmatrix}2&-2\\-1&1\end{pmatrix}\) and decide whether C has an inverse.</p>',D(r'\det(\lambda I-C)=\lambda(\lambda-3)',r'\lambda=0:\ (1,1)^{\mathsf T}',r'\lambda=3:\ (-2,1)^{\mathsf T}')+'<p>The determinant is zero, so no inverse exists. The non-zero vector (1,1) is sent to zero. This is precisely the eigenvalue-zero relation.</p>','eigen',A=[[2,-2],[-1,1]],values=[0,3],vectors=[[1,1],[-2,1]])])
L('algebra','Eigenvalue algebra from the definition','Use powers, inverses and shared vectors with justified restrictions.',
 'Prove eigenvalue properties and apply them to the same non-zero vector.',before('eigen'),
 r'''<h3>Apply the matrix repeatedly</h3><p>Starting with Av=λv, multiplication by A gives A²v=λ²v. Continuing proves the positive-integer power rule. Linearity then proves the polynomial rule; the constant term multiplies I.</p>'''+D(r'A^n\mathbf v=\lambda^n\mathbf v',r'p(A)\mathbf v=p(\lambda)\mathbf v')+r'''<p>The vector stays non-zero even if p(λ)=0. If A is invertible, λ cannot be zero; multiplying Av=λv by A⁻¹ gives A⁻¹v=λ⁻¹v. Negative powers and rational matrix expressions therefore require the relevant inverse to exist.</p><h3>Shared means the same vector</h3><p>If both Av=λv and Bv=μv hold, the same vector gives (αA+βB)v=(αλ+βμ)v and ABv=λμv. Do not combine arbitrary eigenvalues from different eigenvectors or assume two matrices share a complete set just because their eigenvalue lists have the same length.</p><h3>Track the pairing</h3><p>Make a row for each non-zero vector and put its eigenvalues for A, B and the requested expression alongside it. Different original eigenvalues can give the same polynomial output. Preserve the vector-to-value matching even then.</p>''',
 ['Write the eigenvector relation with a non-zero vector.','Derive the requested rule by multiplication and linearity.','For an inverse, establish nonsingularity.','For two matrices, verify that the vector is shared.','Apply the scalar expression in the matching order.'],
 ['The constant term in p(A) multiplies I.','Do not take the reciprocal of a zero eigenvalue.','A common vector is needed to multiply eigenvalues.','Polynomial outputs can coincide.','A proof must apply to a general vector satisfying the hypotheses.'],[
 E('A1','1 · A polynomial can produce zero',r'<p>If \(A\mathbf v=-2\mathbf v\) and \(\mathbf v\ne0\), find an eigenpair of \(A^3-3A+2I\).</p>',D(r'A^2\mathbf v=4\mathbf v,\qquad A^3\mathbf v=-8\mathbf v',r'(A^3-3A+2I)\mathbf v=(-8+6+2)\mathbf v=0\mathbf v')+'<p>The pair is eigenvalue 0 with the original non-zero vector v. The output is zero, but the eigenvector itself is not.</p>','scalar_poly',value=-2,coeff=[1,0,-3,2],result=0),
 E('A2','2 · Prove the inverse rule before using it',r'<p>A is invertible and \(A\mathbf v=3\mathbf v\). Find the eigenvalue of \(2A-A^{-1}\) on v.</p>',D(r'\mathbf v=3A^{-1}\mathbf v',r'A^{-1}\mathbf v=\frac13\mathbf v',r'(2A-A^{-1})\mathbf v=\frac{17}{3}\mathbf v')+'<p>Invertibility justifies applying A⁻¹. The scalar 3 is non-zero, so division is valid.</p>','scalar_rational',value=3,result='17/3'),
 E('A3','3 · Match common vectors',r'<p>The columns of an invertible P are common eigenvectors of A and B. Their eigenvalues are respectively (−1,2,4) and (3,−2,1). Find the diagonal entries for \((2A+B)^2\) in this same order.</p>',D(r'2(-1)+3=1,\qquad2(2)-2=2',r'2(4)+1=9',r'D=\operatorname{diag}(1,4,81)')+'<p>First use the shared-vector relation for 2A+B. Squaring then squares each scalar, preserving the corresponding column of P.</p>','common',aa=[-1,2,4],bb=[3,-2,1],result=[1,4,81]),
 E('A4','4 · Why arbitrary pairing fails',r'<p>Let \(A=\operatorname{diag}(1,2)\) and \(B=\operatorname{diag}(4,3)\). Find the eigenvalues of AB. Is multiplying the two largest eigenvalues valid here?</p>',D(r'AB=\operatorname{diag}(4,6)')+'<p>The complete eigenvalue set is {4,6}. The value 2 belongs to the second coordinate vector, while 4 belongs to the first. Multiplying them to claim 8 would pair different vectors and gives a false result.</p>','product',A=[[1,0],[0,2]],B=[[4,0],[0,3]],result=[4,6])])
C=s.Matrix([[2,1],[1,2]])
L('cayley','Characteristic equations and Cayley–Hamilton','Turn a scalar polynomial into a valid matrix identity.',
 'Reduce powers and calculate inverses using the characteristic identity.',before('algebra'),
 r'''<h3>The matrix satisfies its characteristic polynomial</h3><p>If p(λ)=det(λI−A), the Cayley–Hamilton theorem states p(A)=0, where the right-hand side is the zero matrix. A scalar constant in p becomes that multiple of I.</p>'''+D(r'p(\lambda)=\lambda^3-c_1\lambda^2+c_2\lambda-c_3',r'A^3-c_1A^2+c_2A-c_3I=0')+r'''<p>Use this identity to replace higher powers by lower ones. Multiplying it by A and substituting again reduces A⁴ to a combination of I, A and A². You can also divide scalar polynomials by p(λ), then evaluate the remainder at A.</p><h3>Inverses need a separate check</h3><p>Only if det A≠0 may you multiply by A⁻¹. For a cubic, a non-zero constant term lets you rearrange the resulting identity into an inverse polynomial. Check the result by multiplying by A. A characteristic identity remains true for a singular matrix, but cannot create an inverse for it.</p><h3>Preserve signs and dimensions</h3><p>Use the polynomial corresponding to your actual matrix. When the requested expression includes an inverse square or a shifted power, choose the multiplier or remainder that reduces exactly that expression. All factors that are polynomials in A commute; unrelated matrices need not.</p>''',
 ['Calculate and factor det(λI−A).','Replace each scalar power by a matrix power and the constant by a multiple of I.','Check det A before using negative powers.','Multiply, rearrange and substitute until the requested powers remain.','Verify the final matrix identity directly.'],
 ['The constant term is a multiple of I, not of A.','The zero in p(A)=0 is a zero matrix.','An inverse requires det A≠0.','Keep a consistent determinant sign.','A⁴ is not generally found by raising each entry to the fourth power.'],[
 E('C1','1 · A two-dimensional inverse polynomial',r'<p>Use Cayley–Hamilton to find \(A^{-1}\) for \(A='+T(C)+r'\).</p>',D(r'p(\lambda)=\lambda^2-4\lambda+3',r'A^2-4A+3I=0',r'A^{-1}=\frac{4I-A}{3}='+T(C.inv()))+'<p>The determinant is 3, so A is invertible. Multiplication by A⁻¹ is legitimate, and multiplying the answer by A gives I.</p>','inverse',A=C.tolist()),
 E('C2','2 · A cubic inverse with exact fractions',r'<p>A has characteristic polynomial \(p(\lambda)=\lambda^3-2\lambda^2-5\lambda+6\). Express A⁻¹ as a polynomial in A.</p>',D(r'A^3-2A^2-5A+6I=0',r'A^{-1}=-\frac16A^2+\frac13A+\frac56I')+'<p>The roots are −2,1,3, whose product is −6≠0. Multiplying the proposed polynomial by A and using the characteristic identity verifies the inverse.</p>','ch_inverse',coeff=[1,-2,-5,6],answer=['-1/6','1/3','5/6']),
 E('C3','3 · Reduce the next power',r'<p>Using the same characteristic polynomial, express \(A^4\) using I, A and A².</p>',D(r'A^3=2A^2+5A-6I',r'A^4=2A^3+5A^2-6A',r'A^4=9A^2+4A-12I')+'<p>Substitute the cubic expression into the second line. Collect like matrix powers exactly as for a scalar polynomial remainder.</p>','remainder',coeff=[1,-2,-5,6],power=4,answer=[9,4,-12]),
 E('C4','4 · A singular case cannot be inverted',r'<p>A has characteristic polynomial \(p(\lambda)=\lambda(\lambda-2)(\lambda+3)\). State its characteristic identity and explain whether A⁻¹ can be found from it.</p>',D(r'A^3+A^2-6A=0',r'\det A=0')+'<p>Zero is an eigenvalue, so A is singular and A⁻¹ does not exist. Factoring out A does not allow cancellation by an inverse. The characteristic identity can still reduce positive powers.</p>','singular_ch',coeff=[1,1,-6,0])])
L('diagonal','Diagonalisation and matrix powers','Use matched eigenvector columns to calculate powers and roots.',
 'Construct a diagonalisation and use it without losing column order.',before('cayley'),
 r'''<h3>One column at a time</h3><p>Put independent eigenvectors in the columns of P and their corresponding eigenvalues on the diagonal of D. Then AP=PD. If P is invertible, this becomes P⁻¹AP=D, or A=PDP⁻¹. Distinct real eigenvalues in a two- or three-dimensional problem provide independent eigenvectors. Check det P≠0 rather than attempting to invert a singular matrix.</p>'''+D(r'A=PDP^{-1}',r'A^n=PD^nP^{-1}',r'p(A)=Pp(D)P^{-1}')+r'''<p>Adjacent factors P⁻¹P cancel in a product of powers. Only the diagonal entries are raised to n. If a problem requests all entries, perform both matrix multiplications; leaving a product is incomplete.</p><h3>Roots and limits</h3><p>For a positive diagonal D, choosing real square roots of its entries and conjugating back constructs one square root of A. It need not be the only one. For a fixed real diagonalisation, kⁿAⁿ tends to zero exactly when every |kλᵢ|&lt;1. Equality gives a surviving constant or alternating component, so endpoints are excluded.</p><h3>Coincident outputs</h3><p>A polynomial can send distinct eigenvalues to the same value. The old independent vectors still diagonalise the polynomial matrix. This does not justify claiming that every arbitrary matrix with repeated eigenvalues is diagonalizable.</p>''',
 ['Find all eigenpairs and put them in a fixed order.','Check P is invertible and AP=PD.','Apply the requested scalar function to each diagonal entry.','Calculate all entries when requested.','Check n=1, the square of a root, or boundary cases of a limit.'],
 ['Eigenvectors are columns, not rows.','Reordering P requires the same reordering of D.','P⁻¹ is not generally Pᵀ.','Repeated polynomial outputs do not invalidate the old basis.','Limit endpoints with magnitude 1 do not tend to zero.'],[
 E('D1','1 · Every entry of an nth power',r'<p>Find Aⁿ for positive integers n when \(A=\begin{pmatrix}2&3\\0&5\end{pmatrix}\).</p>',D(r'P=\begin{pmatrix}1&1\\0&1\end{pmatrix}',r'D=\operatorname{diag}(2,5)',r'P^{-1}=\begin{pmatrix}1&-1\\0&1\end{pmatrix}',r'A^n=\begin{pmatrix}2^n&5^n-2^n\\0&5^n\end{pmatrix}')+'<p>Multiplication verifies AP=PD. Inserting n=1 returns A, checking the off-diagonal sign.</p>','power',A=[[2,3],[0,5]],P=[[1,1],[0,1]],values=[2,5]),
 E('D2','2 · Equal outputs after squaring',r'<p>Diagonalise \(A=\begin{pmatrix}1&2\\0&-1\end{pmatrix}\) and hence find A².</p>',D(r'P=\begin{pmatrix}1&-1\\0&1\end{pmatrix}',r'D=\operatorname{diag}(1,-1)',r'A^2=P\operatorname{diag}(1,1)P^{-1}=I')+'<p>The second eigenvector is (−1,1). Squaring gives the same eigenvalue 1 for both independent columns; no vector is lost.</p>','power',A=[[1,2],[0,-1]],P=[[1,-1],[0,1]],values=[1,-1]),
 E('D3','3 · Construct one real matrix square root',r'<p>Find one real B satisfying \(B^2=\begin{pmatrix}4&5\\0&9\end{pmatrix}\).</p>',D(r'P=\begin{pmatrix}1&1\\0&1\end{pmatrix}',r'B=P\operatorname{diag}(2,3)P^{-1}',r'B=\begin{pmatrix}2&1\\0&3\end{pmatrix}')+'<p>Squaring B gives the requested A. This constructs one root; it does not claim uniqueness.</p>','sqrt',A=[[4,5],[0,9]],B=[[2,1],[0,3]]),
 E('D4','4 · Keep both strict limit bounds',r'<p>A is diagonalizable with eigenvalues \(-3,2,5\). Find all real k for which kⁿAⁿ tends to zero.</p>',D(r'|-3k|<1,\qquad|2k|<1,\qquad|5k|<1',r'-\frac15<k<\frac15')+'<p>The last inequality is strongest. At k=1/5 one diagonal power stays 1; at k=−1/5 it alternates. Neither endpoint is admissible.</p>','limit',values=[-3,2,5],bound='1/5')])
P=s.Matrix([[1,2],[1,1]]);R=P*s.diag(-1,4)*P.inv();H=s.Matrix([[1,1,0],[0,1,1],[0,0,1]]);J=H*s.diag(-2,3,5)*H.inv()
L('reconstruct','Reconstruction and similarity','Recover a matrix from its action on independent eigenvectors.',
 'Reconstruct all entries and transport eigenvectors through a similarity.',before('diagonal'),
 r'''<h3>Reverse the diagonalisation</h3><p>Knowing all eigenvalues and corresponding independent vectors determines A=PDP⁻¹. Check det P before using this formula. Eigenvalues alone do not determine every entry. Scaling a column of P by a non-zero factor leaves the reconstructed A unchanged because the inverse changes correspondingly.</p><h3>A change of coordinates</h3>'''+D(r'B=MAM^{-1}',r'A\mathbf v=\lambda\mathbf v',r'B(M\mathbf v)=MA\mathbf v=\lambda(M\mathbf v)')+r'''<p>The transported vector is Mv, not v in general. It is non-zero because M is invertible. Similarity preserves the characteristic polynomial: det(λI−B)=det(M(λI−A)M⁻¹)=det(λI−A). Thus the complete eigenvalue list is unchanged.</p><h3>Apply a function afterwards</h3><p>Once P and D are known, reconstruct A⁻¹ with reciprocal diagonal entries if none are zero, or Aⁿ with diagonal powers. Keep clear whether a letter denotes the original matrix or an eigenvector matrix; the characteristic polynomial of P is not generally the characteristic polynomial of A.</p>''',
 ['Put the supplied corresponding vectors into columns of P.','Prove P is invertible.','Form D in the same order and calculate PDP⁻¹.','For B=MAM⁻¹ transport each vector with M.','Check the result on every supplied vector.'],
 ['Eigenvalues alone do not determine a matrix.','Do not swap the order to P⁻¹DP.','Similarity changes eigenvectors in general.','The transforming matrix must be invertible.','A⁻¹ uses reciprocal eigenvalues, with their original columns.'],[
 E('R1','1 · Reconstruct all four entries',r'<p>A has eigenvalues −1 and 4 with corresponding vectors \((1,1)^{\mathsf T}\) and \((2,1)^{\mathsf T}\). Find A.</p>',D(r'P='+T(P),r'P^{-1}='+T(P.inv()),r'A=P\operatorname{diag}(-1,4)P^{-1}='+T(R))+'<p>The determinant of P is −1. Direct multiplication gives A(1,1)ᵀ=−(1,1)ᵀ and A(2,1)ᵀ=4(2,1)ᵀ.</p>','reconstruct',P=P.tolist(),values=[-1,4],A=R.tolist()),
 E('R2','2 · Transport the vectors',r'<p>For the A in example 1, let \(M=\begin{pmatrix}1&2\\0&1\end{pmatrix}\) and B=MAM⁻¹. Find all eigenpairs of B without expanding B.</p>',D(r'M(1,1)^{\mathsf T}=(3,1)^{\mathsf T}',r'M(2,1)^{\mathsf T}=(4,1)^{\mathsf T}')+'<p>The respective eigenvalues remain −1 and 4. For each vector v, B(Mv)=MAv=λMv. Since det M=1, the transported vectors cannot vanish.</p>','similar',A=R.tolist(),M=[[1,2],[0,1]],values=[-1,4],vectors=[[3,1],[4,1]]),
 E('R3','3 · Three-dimensional reconstruction',r'<p>The columns of \(P='+T(H)+r'\) are eigenvectors with respective eigenvalues −2,3,5. Find A.</p>',D(r'P^{-1}='+T(H.inv()),r'A=P\operatorname{diag}(-2,3,5)P^{-1}',r'A='+T(J))+'<p>All three columns must keep their stated order. Check AP=P diag(−2,3,5), rather than relying only on the trace.</p>','reconstruct',P=H.tolist(),values=[-2,3,5],A=J.tolist()),
 E('R4','4 · Reconstruct the inverse directly',r'<p>Use the eigenpairs of example 1 to find \(A^{-1}\) without inverting the expanded A.</p>',D(r'A^{-1}=P\operatorname{diag}(-1,\tfrac14)P^{-1}',r'A^{-1}='+T(R.inv()))+'<p>Both original eigenvalues are non-zero. The inverse has the same corresponding vectors. Multiplying this result by the reconstructed A gives I.</p>','inverse',A=R.tolist())])
L('systems','Systems, consistency and geometry','Distinguish a unique point, a line, a plane and no common point.',
 'Classify all parameter cases and write every solution with the required free parameters.',before('reconstruct')+'<p>Review <a href="/courses/maths4u-9231-fp1?chapter=fp1_vectors">lines and planes</a>.</p>',
 r'''<h3>Separate uniqueness from existence</h3>'''+D(r'A\mathbf x=\mathbf b')+r'''<p>If det A≠0, there is exactly one solution for every right-hand side. If det A=0, do not conclude there is no solution. Row-reduce the augmented system and inspect its right-hand side. A zero row on the left with a non-zero right-hand side is a contradiction. Otherwise free variables describe all solutions.</p><h3>Handle exceptional parameters before dividing</h3><p>Find every zero of det A(k). The ordinary formula works only away from those values. Substitute each exceptional value back into the original equations and determine any consistency conditions on other parameters. Never divide by k−k₀ and then claim to have covered k=k₀.</p><h3>Geometric meaning</h3><p>Each non-degenerate linear equation in three variables describes a plane. A unique solution is their only common point. A consistent system with one free parameter gives a common line; two free parameters give a common plane. Contradictory equations have no common point. A homogeneous system always contains zero and has a non-zero solution exactly when its square coefficient matrix is singular.</p><h3>Write a complete family</h3>'''+D(r'\mathbf x=\mathbf p+t\mathbf d,\qquad t\in\mathbb R')+r'''<p>Verify A p=b and A d=0; check that the family has every free variable found in elimination. Two equivalent parameterisations can describe the same line. Additional linear or quadratic conditions must be imposed on the whole family, retaining every valid parameter value.</p>''',
 ['Write the coefficient and augmented matrices in the original variable order.','Find all exceptional parameter values using the determinant.','Eliminate separately in every exceptional case.','State consistency conditions and every free parameter.','Substitute the complete family and describe its geometry.'],
 ['A zero determinant does not distinguish no solution from infinitely many.','Apply row operations to the right-hand side too.','Do not divide by a parameter expression before treating zero.','A consistent homogeneous system always has the zero solution.','A line and a plane require different numbers of free parameters.'],[
 E('S1','1 · A unique point',r'<p>Solve \(x+y+z=2\), \(x+2y+3z=2\), \(2x+y+z=3\).</p>',D(r'(2x+y+z)-(x+y+z)=1',r'x=1,\qquad y+z=1,\qquad y+2z=0',r'(x,y,z)=(1,2,-1)')+'<p>The coefficient determinant is non-zero. Substitution in all three original equations verifies the unique common point.</p>','system',A=[[1,1,1],[1,2,3],[2,1,1]],b=[2,2,3],solution=[1,2,-1]),
 E('S2','2 · A whole common line',r'<p>Solve \(x+y+z=4\), \(x+2y+3z=7\), \(2x+3y+4z=11\).</p>',D(r'R_3=R_1+R_2,\qquad y+2z=3',r'z=t,\quad y=3-2t,\quad x=1+t',r'\mathbf x=(1,3,0)^{\mathsf T}+t(1,-2,1)^{\mathsf T}')+'<p>The third equation is the sum of the first two, including the right-hand side. One free variable remains, so the planes meet in this common line.</p>','system',A=[[1,1,1],[1,2,3],[2,3,4]],b=[4,7,11],solution=['1+t','3-2*t','t']),
 E('S3','3 · The same coefficients, an inconsistent total',r'<p>Solve \(x+y+z=4\), \(x+2y+3z=7\), \(2x+3y+4z=12\).</p>',D(r'R_3-R_1-R_2:\quad0=12-4-7=1')+'<p>The contradiction means there is no common point. Keeping the same singular coefficient matrix does not preserve consistency when the right-hand side changes.</p>','inconsistent',A=[[1,1,1],[1,2,3],[2,3,4]],b=[4,7,12]),
 E('S4','4 · Two free parameters form a plane',r'<p>Solve \(x-2y+z=3\), \(2x-4y+2z=6\), \(-x+2y-z=-3\).</p>',D(r'y=s,\quad z=t,\quad x=3+2s-t',r'\mathbf x=(3,0,0)^{\mathsf T}',r'\quad+s(2,1,0)^{\mathsf T}+t(-1,0,1)^{\mathsf T}')+'<p>All three equations describe the same plane. Both real parameters are unrestricted, and their independent direction vectors produce every point of it.</p>','system',A=[[1,-2,1],[2,-4,2],[-1,2,-1]],b=[3,6,-3],solution=['3+2*s-t','s','t'])])
L('mixed','Mixed matrix applications','Combine matrix methods with parameters, vector geometry and iteration.',
 'Choose a justified method and keep exceptional cases and complete geometric answers.',before('systems')+'<p>The invariant-plane and shortest-distance applications also require the vector product, scalar product and equations of lines from Further Pure 1.</p>',
 r'''<h3>Plan before expanding</h3><p>A problem may supply an eigenvector, a characteristic equation, a parameter-dependent system and a geometric condition. Decide which information answers each part. A known eigenvector can evaluate a large power without calculating the full matrix; a complete matrix expression requires enough independent eigenvectors.</p><h3>Invariant planes</h3><p>If e and f are independent eigenvectors, every image of se+tf is λse+μtf, which remains in their plane. When both eigenvalues are non-zero, any target ce+df has preimage (c/λ)e+(d/μ)f, so the plane maps onto itself. A normal e×f gives its Cartesian equation. An invariant plane's normal need not be a right eigenvector of A.</p><h3>Nearest points on solution lines</h3>'''+D(r'\mathbf r=\mathbf p+t\mathbf d',r'|\mathbf r|^2=|\mathbf p|^2+2t\mathbf p\cdot\mathbf d+t^2|\mathbf d|^2',r't_{\min}=-\frac{\mathbf p\cdot\mathbf d}{|\mathbf d|^2}')+r'''<p>The quadratic coefficient is positive for a non-zero direction, proving this is the unique minimum. Give both the point and the distance when requested, then verify any extra constraints.</p><h3>Parameters and iteration</h3><p>Use the given parameter domain to check non-zero and distinct eigenvalues. Do not introduce a value excluded by that domain. For repeated updates xₙ₊₁=Axₙ, write xₙ=Aⁿx₀ and decompose x₀ into the known independent vectors. Preserve all components, including a component whose eigenvalue is 1.</p>''',
 ['Identify the requested algebraic and geometric outputs.','Record parameter restrictions before applying inverses or dividing.','Choose eigenvector, characteristic or elimination methods part by part.','Verify the resulting vectors, equations and full solution families.','Check endpoints, non-zero conditions and any extra constraints.'],
 ['An invariant plane need not have a normal that is a right eigenvector.','Mapped into and mapped onto need different justifications.','A least distance is the positive square root of the minimum squared distance.','A matrix parameter and a free solution parameter play different roles.','Iteration must retain every initial eigenvector component.'],[
 E('M1','1 · A parameter range justifies the method',r'<p>For \(a>2\), consider \(A=\begin{pmatrix}a&1&0\\0&2&0\\0&0&-1\end{pmatrix}\). Show it is invertible with three distinct eigenvalues, and find a vector for each.</p>',D(r'\det A=-2a\ne0',r'\lambda=a:\ (1,0,0)^{\mathsf T}',r'\lambda=2:\ (1,2-a,0)^{\mathsf T}',r'\lambda=-1:\ (0,0,1)^{\mathsf T}')+'<p>The restriction a&gt;2 keeps a different from 2 and −1, and all three values non-zero. The second vector remains non-zero. Check each relation directly.</p>','parameter_family'),
 E('M2','2 · An invariant plane from two vectors',r'<p>A has eigenvectors \(\mathbf e=(1,0,1)^{\mathsf T}\), \(\mathbf f=(0,1,1)^{\mathsf T}\) with eigenvalues 2 and −3. Find the plane they span and prove it maps onto itself.</p>',D(r'\mathbf e\times\mathbf f=(-1,-1,1)^{\mathsf T}',r'x+y-z=0',r'A(s\mathbf e+t\mathbf f)=2s\mathbf e-3t\mathbf f')+'<p>The normal gives the plane equation. For any target ce+df in it, (c/2)e−(d/3)f maps to that target. Both eigenvalues are non-zero, so this proves onto, not just into.</p>','plane',e=[1,0,1],f=[0,1,1],normal=[-1,-1,1]),
 E('M3','3 · A least distance on a solution line',r'<p>Find the point of \(\mathbf r=(1,2,0)^{\mathsf T}+t(1,-1,2)^{\mathsf T}\) nearest the origin, and its distance.</p>',D(r'|\mathbf r|^2=5-2t+6t^2',r't=\frac16,\qquad\mathbf r_{\min}=(\tfrac76,\tfrac{11}6,\tfrac13)^{\mathsf T}',r'd_{\min}=\sqrt{\frac{29}{6}}')+'<p>The positive coefficient 6 makes this a minimum. The position vector at this parameter is perpendicular to the line direction, giving an independent check.</p>','nearest',point=[1,2,0],direction=[1,-1,2],parameter='1/6',result=['7/6','11/6','1/3'],squared='29/6'),
 E('M4','4 · Repeated updates preserve both components',r'<p>Let \(A=\begin{pmatrix}3&-2\\0&1\end{pmatrix}\), \(\mathbf x_0=(2,1)^{\mathsf T}\) and \(\mathbf x_{n+1}=A\mathbf x_n\). Find xₙ for every n≥0.</p>',D(r'\mathbf x_0=(1,0)^{\mathsf T}+(1,1)^{\mathsf T}',r'A(1,0)^{\mathsf T}=3(1,0)^{\mathsf T}',r'A(1,1)^{\mathsf T}=(1,1)^{\mathsf T}',r'\mathbf x_n=(3^n+1,1)^{\mathsf T}')+'<p>The first component grows with 3ⁿ; the eigenvalue-1 component persists. At n=0 the expression returns (2,1), and applying A produces the n+1 expression.</p>','iteration',A=[[3,-2],[0,1]],initial=[2,1])])
